        long res = 1;
        long b = base;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * b % mod;
            b = b * b % mod;
            exp >>= 1;
        }
        return res;
    }

    private long getCombination(long[] fact, long[] invFact, int n, int m) {
        return fact[n] * invFact[m] % mod * invFact[n - m] % mod;
    }
}
