#include <bits/stdc++.h>
using namespace std;

const int mod = 998244353;

long long powMod(long long base, long long exp) {
    long long res = 1;
    long long b = base;
    while (exp > 0) {
        if (exp & 1) res = res * b % mod;
        b = b * b % mod;
        exp >>= 1;
    }
    return res;
}

long long getCombination(const vector<long long>& fact, const vector<long long>& invFact, int n, int m) {
    return fact[n] * invFact[m] % mod * invFact[n - m] % mod;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long k;
    cin >> n >> k;

    vector<long long> fact(200001, 1);
    vector<long long> invFact(200001, 1);
    for (int i = 1; i <= 200000; i++) {
        fact[i] = fact[i - 1] * i % mod;
        invFact[i] = invFact[i - 1] * powMod(i, mod - 2) % mod;
    }

    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }
    if (k == 0) {
        cout << fact[n] << "\n";
        return 0;
    }

    int m = (int)(n - k);
    long long total = 0;
    for (int i = 0; i <= m; i++) {
        long long c = getCombination(fact, invFact, m, i);
        long long val = powMod(m - i, n);
        if (i % 2 == 0) {
            total = (total + c * val) % mod;
        } else {
            total = (total - c * val + mod) % mod;
        }
    }

    long long res = 2LL * fact[n] % mod * invFact[n - m] % mod * total % mod * invFact[m] % mod;
    cout << res << "\n";

    return 0;
}
